Layout.Stylesheet:
/* The whole table: font size and color are passed on to the cells. */
table.prices { font-size: 9pt; line-height: 12pt; color: #263238; padding: 2pt 4pt }

/* Table head: dark row, white bold text, counted on its own. */
table.prices tablehead tr { background-color: #37586e }
table.prices tablehead td { color: #ffffff; font-weight: bold }

/* Zebra stripes for the rows of the body. */
table.prices tr:nth-child(even) { background-color: #e6edf1 }

/* First column (article number) bold, the last two columns right aligned. */
table.prices td:first-child { font-weight: bold }
table.prices td:nth-child(4), table.prices td:nth-child(5) { text-align: right }

/* Classes from the layout and the data. A group row has no stripe:
   same specificity as the zebra rule, but later in the stylesheet. */
table.prices tr.sale { color: #a33a2a }
table.prices tr.group { background-color: #ffffff }
table.prices tr.group td { font-size: 11pt; font-weight: bold; padding-top: 8pt; border-bottom-width: 0.5pt }

/* Headline and note. */
paragraph.title { font-size: 16pt; line-height: 20pt; font-weight: bold; margin-bottom: 6pt }
paragraph.note { font-size: 8pt; color: #546e7a; margin-top: 6pt }
